"""Python/PyStan 3.10.0 port of gp_rstan.R (GP with ARD sq-exp kernel + linear mean)."""

import csv
import inspect
import json
import os

import numpy as np
import stan

APP = os.path.dirname(os.path.abspath(__file__))

stan_code = """
functions {
  matrix cov_ard_sqexp(matrix X, vector rho, real alpha, real jitter) {
    int N = rows(X);
    int D = cols(X);
    matrix[N, N] K;

    for (i in 1:N) {
      K[i, i] = square(alpha) + jitter;
      for (j in (i + 1):N) {
        real s = 0;
        for (d in 1:D) {
          real t = (X[i, d] - X[j, d]) / rho[d];
          s += t * t;
        }
        K[i, j] = square(alpha) * exp(-0.5 * s);
        K[j, i] = K[i, j];
      }
    }
    return K;
  }

  matrix cross_cov_ard(matrix X, matrix X_new, vector rho, real alpha) {
    int N = rows(X);
    int M = rows(X_new);
    int D = cols(X); // == cols(X_new)
    matrix[N, M] Kx;
    for (i in 1:N) {
      for (j in 1:M) {
        real s = 0;
        for (d in 1:D) {
          real t = (X[i, d] - X_new[j, d]) / rho[d];
          s += t * t;
        }
        Kx[i, j] = square(alpha) * exp(-0.5 * s);
      }
    }
    return Kx;
  }
}

data {
  int<lower=1> N;
  int<lower=1> D;
  matrix[N, D] X;
  int<lower=1> P;
  matrix[N, P] H;
  vector[N] y;
  real<lower=0> jitter;

  int<lower=0> N_new;
  matrix[N_new, D] X_new;
  matrix[N_new, P] H_new;
}

parameters {
  vector[P] beta;
  real<lower=0> alpha;
  vector<lower=0>[D] rho;
  real<lower=0> sigma;
}

model {
  // mu, K and L_K kept as model-local variables (not transformed parameters)
  // so the N x N matrices are not stored for every saved draw. The target
  // density -- and hence the posterior sampling -- is unchanged.
  vector[N] mu = H * beta;
  matrix[N, N] K = cov_ard_sqexp(X, rho, alpha, jitter)
                   + diag_matrix(rep_vector(square(sigma), N));
  matrix[N, N] L_K = cholesky_decompose(K);

  beta  ~ normal(0, 1);
  alpha ~ normal(0, 1.5);
  rho   ~ lognormal(0, 1);
  sigma ~ normal(0, 0.5);
  y ~ multi_normal_cholesky(mu, L_K);
}

generated quantities {
  vector[N_new] y_new;
  if (N_new > 0) {
    matrix[N, N] L_K = cholesky_decompose(cov_ard_sqexp(X, rho, alpha, jitter)
                       + diag_matrix(rep_vector(square(sigma), N)));
    matrix[N, N_new] K_x_xnew = cross_cov_ard(X, X_new, rho, alpha);
    matrix[N_new, N_new] K_new = cov_ard_sqexp(X_new, rho, alpha, jitter);
    vector[N] resid = y - (H * beta);

    vector[N] alpha_vec = mdivide_left_tri_low(L_K, resid);
    alpha_vec = mdivide_left_tri_low(L_K', alpha_vec);

    vector[N_new] f_mean = (K_x_xnew' * alpha_vec);
    matrix[N, N_new] v = mdivide_left_tri_low(L_K, K_x_xnew);
    vector[N_new] f_var = to_vector(diagonal(K_new)) - to_vector(columns_dot_self(v));
    for (m in 1:N_new) {
      real m_mean = (H_new[m] * beta) + f_mean[m];
      real m_sd   = sqrt(f_var[m] + square(sigma));
      y_new[m] = normal_rng(m_mean, m_sd);
    }
  }
}
"""


def read_matrix(path):
    return np.genfromtxt(path, delimiter=",", skip_header=1, ndmin=2)


def main():
    with open(os.path.join(APP, "meta_public.json")) as f:
        meta_pub = json.load(f)

    train_X = read_matrix(os.path.join(APP, "train_X.csv"))
    test_X = read_matrix(os.path.join(APP, "test_X.csv"))
    train_y = read_matrix(os.path.join(APP, "train_y.csv"))[:, 0]

    P = int(meta_pub["P"])
    jitter = float(meta_pub["jitter"])

    N, D = train_X.shape
    N_new = test_X.shape[0]

    H = np.column_stack([np.ones(N), train_X[:, 0], train_X[:, 1]])
    if N_new > 0:
        H_new = np.column_stack([np.ones(N_new), test_X[:, 0], test_X[:, 1]])
        X_new = test_X
    else:
        H_new = np.zeros((0, P))
        X_new = np.zeros((0, D))

    data = {
        "N": N, "D": D, "X": train_X,
        "P": P, "H": H, "y": train_y,
        "jitter": jitter,
        "N_new": N_new,
        "X_new": X_new,
        "H_new": H_new,
    }

    posterior = stan.build(stan_code, data=data, random_seed=1)

    # RStan: chains=4, iter=2000, warmup=1000, thin=2 -> 1000 post-warmup
    # iterations per chain, 500 saved draws per chain.
    requested = {
        "num_chains": 4,
        "num_samples": 1000,
        "num_warmup": 1000,
        "num_thin": 2,
        "save_warmup": False,
        "refresh": 200,
        "delta": 0.93,          # control$adapt_delta
        "max_depth": 14,        # control$max_treedepth
        "gamma": 0.05,          # control$adapt_gamma
        "kappa": 0.75,          # control$adapt_kappa
        "t0": 10,               # control$adapt_t0
        "init_buffer": 100,     # control$adapt_init_buffer
        "term_buffer": 50,      # control$adapt_term_buffer
        "window": 25,           # control$adapt_window
        "init_radius": 0.1,     # init_r
    }
    # Some argument names differ across pystan/httpstan versions; adapt here.
    aliases = {
        "delta": ["delta", "adapt_delta"],
        "max_depth": ["max_depth", "max_treedepth"],
        "gamma": ["gamma", "adapt_gamma"],
        "kappa": ["kappa", "adapt_kappa"],
        "t0": ["t0", "adapt_t0"],
        "init_buffer": ["init_buffer", "adapt_init_buffer"],
        "term_buffer": ["term_buffer", "adapt_term_buffer"],
        "window": ["window", "adapt_window"],
        "init_radius": ["init_radius", "init_r"],
        "num_thin": ["num_thin", "thin"],
    }
    try:
        params = inspect.signature(posterior.sample).parameters
        explicit = set(params) - {"kwargs", "args"}
        has_var_kw = any(p.kind is inspect.Parameter.VAR_KEYWORD
                         for p in params.values())
    except (TypeError, ValueError):
        explicit, has_var_kw = set(), True

    kwargs = {}
    for key, value in requested.items():
        name = key
        if not has_var_kw or explicit:
            for cand in aliases.get(key, [key]):
                if cand in explicit:
                    name = cand
                    break
        kwargs[name] = value

    while True:
        try:
            fit = posterior.sample(**kwargs)
            break
        except TypeError as exc:
            msg = str(exc)
            swapped = False
            for key, cands in aliases.items():
                for i, cand in enumerate(cands):
                    if cand in kwargs and cand in msg:
                        alt = cands[(i + 1) % len(cands)]
                        if alt != cand:
                            kwargs[alt] = kwargs.pop(cand)
                            swapped = True
                        break
                if swapped:
                    break
            if not swapped:
                raise

    alpha_post = float(np.mean(fit["alpha"]))
    sigma_post = float(np.mean(fit["sigma"]))
    rho_post = np.asarray(fit["rho"]).reshape(D, -1).mean(axis=1)
    beta_post = np.asarray(fit["beta"]).reshape(P, -1).mean(axis=1)

    print("Posterior means:")
    print("alpha:", alpha_post)
    print("sigma:", sigma_post)
    print("rho:  ", " ".join(f"{v:.6f}" for v in rho_post))
    print("beta: ", " ".join(f"{v:.6f}" for v in beta_post))

    def write_csv(path, values):
        with open(os.path.join(APP, path), "w", newline="") as f:
            w = csv.writer(f)
            for v in np.atleast_1d(values):
                w.writerow([float(v)])

    write_csv("alpha_est.csv", alpha_post)
    write_csv("sigma_est.csv", sigma_post)
    write_csv("rho_est.csv", rho_post)
    write_csv("beta_est.csv", beta_post)


if __name__ == "__main__":
    main()
